@push('scripts')<script>(()=>{const root=document.getElementById('reservation-status');let busy=false;setInterval(async()=>{if(document.hidden||busy)return;busy=true;try{const r=await fetch(root.dataset.url,{headers:{Accept:'application/json'}});if(!r.ok)return;const d=await r.json();document.getElementById('reservation-status-badge').textContent=d.status;document.getElementById('reservation-status-badge').dataset.status=d.status_code;document.getElementById('rv-payment-status').textContent=({paid:'Lunas',partial:'Sebagian dibayar',unpaid:'Belum dibayar'})[d.payment_status]||d.payment_status;for(const [id,value] of [['rv-paid',d.paid],['rv-remaining',d.remaining]])document.getElementById(id).textContent='Rp '+new Intl.NumberFormat('id-ID').format(value);}catch{}finally{busy=false;}},15000);})();</script>@endpush
